const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const STORE = 'aceeMasterReviewer.v1';
const defaults = {view:'dashboard', done:{}, logs:[], quizScores:{}, studyDays:[], notes:{}, plan:'60', planStart:'', mockScores:[]};
let state = loadState();
function loadState(){try{return {...defaults,...JSON.parse(localStorage.getItem(STORE)||'{}')}}catch{return {...defaults}}}
function save(){localStorage.setItem(STORE,JSON.stringify(state));renderStats()}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setView(v){state.view=v;save();$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#current-section').textContent=({dashboard:'Dashboard',research:'ACEE research',english:'English & Language',reading:'Reading comprehension',math:'Mathematics',science:'General science',reasoning:'Abstract & logical reasoning',mocks:'Mock examinations',videos:'Video library',studyplan:'Study plans',tracker:'Progress tracker',formula:'Formula sheet',glossary:'Glossary'})[v]||v;render();$('#sidebar').classList.remove('open');window.scrollTo(0,0)}
function toggleDone(id){state.done[id]=!state.done[id];save();render()}
