const glossary=[
['Antecedent','The noun or noun phrase to which a pronoun refers.'],['Bias','A tendency that may influence how information is selected or interpreted.'],['Claim','A statement that an author asks readers to accept.'],['Connotation','The feelings or associations linked to a word beyond its literal meaning.'],['Deduction','Reasoning from general premises to a conclusion that follows logically.'],['Domain','The set of allowed input values of a function.'],['Evidence','Information used to support or evaluate a claim.'],['Inference','A conclusion drawn from clues and evidence rather than stated directly.'],['Independent variable','The factor deliberately changed in an experiment.'],['Mean','The sum of numerical values divided by the number of values.'],['Median','The middle value in an ordered data set.'],['Mole','An amount of substance containing approximately 6.022 × 10²³ specified entities.'],['Parallel structure','Consistent grammatical forms in coordinated elements.'],['Passive voice','A construction in which the grammatical subject receives the action.'],['Probability','A numerical measure of the likelihood of an event.'],['Register','The level of formality or style appropriate to a context.'],['Syllogism','A deductive argument using premises to reach a conclusion.'],['Tone','The author’s attitude toward the subject or audience.'],['Validity','In logic, a deductive argument is valid when its conclusion follows from its premises.']
];
function renderStats(){const total=modules.reduce((n,m)=>n+m.topics.length,0),completed=Object.values(state.done).filter(Boolean).length;const el=$('#dash-progress');if(el)el.style.width=Math.min(100,completed/total*100)+'%';const t=$('#dash-completed');if(t)t.textContent=completed;const a=$('#dash-accuracy');if(a){const vals=Object.values(state.quizScores);a.textContent=vals.length?Math.round(vals.reduce((x,y)=>x+y,0)/vals.length)+'%':'—'}const l=$('#dash-logs');if(l)l.textContent=state.logs.length}
function render(){const app=$('#app');const views={dashboard:dashboard,research:research,english:()=>modulePage('english'),reading:()=>modulePage('reading'),math:()=>modulePage('math'),science:()=>modulePage('science'),reasoning:()=>modulePage('reasoning'),mocks:mocks,videos:videoPage,studyplan:studyPlan,tracker:tracker,formula:formula,glossary:glossaryPage};app.innerHTML=(views[state.view]||dashboard)();bindPage();renderStats()}
function dashboard(){const completed=Object.values(state.done).filter(Boolean).length,total=modules.reduce((n,m)=>n+m.topics.length,0);return `<div class="hero"><div><div class="eyebrow">College entrance preparation · Philippines</div><h1>Prepare with structure.<br>Measure what you learn.</h1><p>A central study hub for the five proposed ACEE preparation areas, built around lessons, practice, review cycles, and measurable progress.</p><div class="actions"><button class="btn btn-primary" data-go="research">Read research report →</button><button class="btn" data-go="english">Start English lessons</button></div></div><div class="hero-side"><div class="eyebrow">YOUR STUDY SNAPSHOT</div><div class="big">${completed}/${total}</div><div>topics marked complete</div><div class="progress-track" style="margin:15px 0 9px"><span id="dash-progress" style="width:${total?completed/total*100:0}%"></span></div><small>Progress is saved locally in this browser.</small></div></div>
<div class="stats"><div class="stat"><div class="label">Topics completed</div><div class="value" id="dash-completed">${completed}</div><div class="sub">Across all five modules</div></div><div class="stat"><div class="label">Practice accuracy</div><div class="value" id="dash-accuracy">—</div><div class="sub">Average of completed quiz attempts</div></div><div class="stat"><div class="label">Study sessions</div><div class="value" id="dash-logs">${state.logs.length}</div><div class="sub">Logged sessions</div></div><div class="stat"><div class="label">Mock exams recorded</div><div class="value">${state.mockScores.length}</div><div class="sub">Self-scored practice exams</div></div></div>
<div class="section-head"><div><h2>Study modules</h2><p>Start with a diagnostic, then focus on the topics that need work.</p></div><span class="tag">5 CORE AREAS</span></div><div class="grid">${modules.map(m=>`<div class="card"><div class="card-icon">${m.icon}</div><div><span class="tag">${m.tag}</span></div><h3>${m.title}</h3><p>${m.desc}</p><div class="card-bottom"><span>${m.topics.length} topic groups · ${m.target}</span><button class="btn" data-go="${m.id}">Open →</button></div></div>`).join('')}</div>
<div class="section-head"><div><h2>Study tools</h2><p>Plans, practice resources, and performance review.</p></div></div><div class="grid four">${[['mocks','Mock examinations','Three suggested practice levels.'],['videos','Video library','Curated education channels and resources.'],['studyplan','Study plans','30-, 60-, and 90-day structures.'],['tracker','Progress tracker','Log sessions and diagnose mistakes.']].map(x=>`<div class="card"><h3>${x[1]}</h3><p>${x[2]}</p><div class="card-bottom"><button class="btn" data-go="${x[0]}">Open tool →</button></div></div>`).join('')}</div>
<div class="notice"><strong>Accuracy note:</strong> The five subject areas are a working preparation framework, not a verified official ACEE blueprint. This website is an independent study aid, not an official university resource.</div>`}
function research(){return `<div class="eyebrow">Orientation</div><h1>ACEE research & verification</h1><p class="lead">Separate confirmed university information from general entrance-exam preparation assumptions.</p><div class="notice blue"><strong>Important distinction</strong>The five areas used in this reviewer—English, Reading Comprehension, Mathematics, Science, and Abstract/Logical Reasoning—are proposed preparation categories. They must not be represented as an official test blueprint without confirmation from Ateneo de Naga University.</div><div class="grid two"><div class="card"><span class="tag green">Official source</span><h3>Ateneo de Naga University</h3><p>Use official admissions announcements to verify application requirements, examination dates, fees, and current procedures.</p><div class="card-bottom"><a href="https://www.adnu.edu.ph/apply/" target="_blank" rel="noopener">Official application page ↗</a></div></div><div class="card"><span class="tag">Curriculum source</span><h3>DepEd learning resources</h3><p>Use Philippine K–12 curriculum guides to build subject knowledge. Curriculum alignment does not confirm ACEE item distribution.</p><div class="card-bottom"><a href="https://lrmds.deped.gov.ph/" target="_blank" rel="noopener">DepEd Learning Portal ↗</a></div></div></div><div class="section-head"><div><h2>Verification table</h2><p>Re-check admission details for the intended academic year.</p></div></div><div class="table-wrap"><table><thead><tr><th>Detail</th><th>Status</th><th>What to do</th></tr></thead><tbody>${[['Official exam name','Check current university wording','Use the name in the latest official notice.'],['Exact sections and topic weights','Not independently confirmed','Do not assume the five areas are official.'],['Number of items and time limits','Unverified','Use suggested timing only for practice.'],['Scoring and admission cutoffs','Unverified','Consult current university policies.'],['Calculator policy','Unverified','Confirm with the admissions office.'],['Official sample test/reviewer','Not located in sources reviewed','Do not label third-party material official.'],['Admission schedule and fee','Year-specific','Check the current official application page.']].map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table></div><div class="section-head"><div><h2>Source directory</h2><p>Official policy sources first; supplementary learning resources second.</p></div></div><div class="resource"><div class="play">AD</div><div><h3>Ateneo de Naga University — Apply</h3><p>University application and admission announcements.</p><a href="https://www.adnu.edu.ph/apply/" target="_blank" rel="noopener">Open official page ↗</a></div></div><div class="resource"><div class="play">AD</div><div><h3>Ateneo de Naga University — Admissions</h3><p>Admissions and aid office information. If the URL changes, use the main university website.</p><a href="https://www.adnu.edu.ph/" target="_blank" rel="noopener">Open university website ↗</a></div></div><div class="resource"><div class="play">D</div><div><h3>DepEd Learning Portal</h3><p>Philippine curriculum learning resources.</p><a href="https://lrmds.deped.gov.ph/" target="_blank" rel="noopener">Open learning portal ↗</a></div></div><div class="resource"><div class="play">K</div><div><h3>Khan Academy</h3><p>Supplementary structured lessons and practice.</p><a href="https://www.khanacademy.org/" target="_blank" rel="noopener">Open Khan Academy ↗</a></div></div><p class="small muted">Research limitation: a public page not found during preparation is not proof that the university has no internal or unpublished specifications. Verify all current admission details directly with ADNU.</p>`}
function modulePage(id){const m=modules.find(x=>x.id===id);const isEng=id==='english';const lessonList=isEng?englishLessons:[];return `<div class="eyebrow">${m.tag} · STUDY MODULE</div><h1>${m.title}</h1><p class="lead">${m.desc}</p><div class="notice blue"><strong>Coverage and completion</strong>This module includes the complete topic map for the reviewer. Lessons and question banks are being expanded in installments; topic labels do not mean every promised question set is already included.</div><div class="two-col"><div><div class="section-head"><div><h2>Topic checklist</h2><p>Mark each topic after you can explain it and answer practice questions independently.</p></div></div><div class="topic-list">${m.topics.map((t,i)=>{let id2=id+'-'+i;return `<label class="topic-row"><input class="check" type="checkbox" data-done="${id2}" ${state.done[id2]?'checked':''}><span><strong>${t}</strong><small>${state.done[id2]?'Marked complete':'Review lesson, examples, and practice'}</small></span></label>`}).join('')}</div></div><div><div class="panel"><h3>Module target</h3><div class="kpi">${m.target}</div><p class="small muted">Original practice items with answer explanations are planned for the complete reviewer. Use the available quiz below as a checkpoint, not as a full-length test.</p><div class="divider"></div><h3>Recommended learning cycle</h3><ol class="list-clean"><li>Study the concept.</li><li>Work through an example.</li><li>Answer questions without notes.</li><li>Review each error.</li><li>Revisit after a delay.</li></ol><button class="btn btn-dark" data-go="tracker">Log a study session</button></div><div class="panel" style="margin-top:12px"><h3>Personal notes</h3><textarea class="field" id="notes-${id}" placeholder="Record difficult concepts, mistakes, and questions...">${esc(state.notes[id]||'')}</textarea><button class="btn" data-save-note="${id}">Save notes</button></div></div></div>
${isEng?`<div class="section-head"><div><h2>English lessons</h2><p>Foundational explanations and worked examples.</p></div></div>${lessonList.map((l,i)=>`<details class="accordion" ${i===0?'open':''}><summary>${i+1}. ${l.title}</summary><div class="inside"><p>${l.body}</p>${l.table?`<div class="table-wrap"><table><tbody>${l.table.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}${l.example?`<div class="example"><strong>Worked example</strong><br>${l.example}</div>`:''}${l.mistake?`<p><strong>Common trap:</strong> ${l.mistake}</p>`:''}</div></details>`).join('')}`:subjectLessonContent(id)}
<div class="section-head"><div><h2>Practice checkpoint</h2><p>Answer each item and review the rationale.</p></div><span class="tag">${(quizBank[id]||[]).length} available questions</span></div>${quizMarkup(id)}`}
function subjectLessonContent(id){if(id==='math')return `<div class="section-head"><div><h2>Core formulas and methods</h2><p>Start with these foundations before moving to multi-step questions.</p></div></div><div class="grid two">${[['Percentages','Percentage = (part ÷ whole) × 100%. Percent change = (change ÷ original) × 100%.','Example: 25% of 360 = 0.25 × 360 = 90.'],['Linear equations','Apply inverse operations equally to both sides.','Example: 3x + 7 = 25 → 3x = 18 → x = 6.'],['Factoring','Difference of squares: a² − b² = (a − b)(a + b).','Example: x² − 9 = (x − 3)(x + 3).'],['Rate problems','Speed = distance ÷ time. Distance = speed × time. Time = distance ÷ speed.','Example: 150 km ÷ 3 h = 50 km/h.'],['Geometry','Triangle area = ½bh. Rectangle area = lw. Circle area = πr².','Check units and convert measurements before substituting.'],['Statistics','Mean = sum ÷ number of values. Median = middle value after sorting.','For 4, 6, 8, 10: mean = 28 ÷ 4 = 7.']].map(x=>`<div class="lesson"><h3>${x[0]}</h3><p>${x[1]}</p><div class="example">${x[2]}</div></div>`).join('')}</div>`;
if(id==='science')return `<div class="grid two">${[['Biology','Cells are the basic structural and functional units of life. Mitochondria are a major site of aerobic respiration; chloroplasts carry out photosynthesis in plants and algae.','Review cell structures, heredity, homeostasis, body systems, ecology, and evolution.'],['Chemistry','Atomic number equals proton count. Mass number equals protons plus neutrons. Chemical equations must conserve atoms.','Example: 2H₂ + O₂ → 2H₂O. Four H atoms and two O atoms appear on each side.'],['Physics','Speed = distance/time. Acceleration = change in velocity/time. Newton’s laws describe relationships among motion and forces.','Example: 100 m ÷ 20 s = 5 m/s average speed.'],['Earth and Space Science','Plate motion relates to earthquakes and volcanoes. Weather describes short-term atmospheric conditions; climate describes longer-term patterns.','In the Philippines, apply scientific principles to typhoons, monsoons, faults, volcanoes, and disaster preparedness.']].map(x=>`<div class="lesson"><h3>${x[0]}</h3><p>${x[1]}</p><div class="example">${x[2]}</div></div>`).join('')}</div>`;
if(id==='reading')return `<div class="lesson"><h3>Reading method: claim, evidence, inference</h3><ol class="list-clean"><li>Identify the topic and central claim.</li><li>Separate explicit statements from your inferences.</li><li>Locate the evidence supporting each answer.</li><li>Check whether an answer overstates what the passage says.</li><li>Eliminate choices that are plausible in real life but unsupported by the text.</li></ol><div class="example"><strong>Original mini-passage:</strong> A school installed shaded seating and trees near a courtyard. Students reported using the courtyard more often during hot afternoons. The school has not yet measured temperature changes.<br><br><strong>Supported inference:</strong> The shaded area may have become more comfortable to students. <strong>Unsupported claim:</strong> The project definitely reduced the courtyard’s temperature by a specific amount.</div></div>`;
return `<div class="lesson"><h3>Reasoning method: find a rule, test it, then commit</h3><ol class="list-clean"><li>Check simple changes first: count, position, rotation, size, shading, and alternation.</li><li>For number sequences, test differences, ratios, and alternating rules.</li><li>For syllogisms, accept only conclusions that must follow from the premises.</li><li>For if–then statements, remember that P → Q and P imply Q, but Q alone does not prove P.</li><li>If a visual pattern is unfamiliar, describe each change systematically rather than guessing from appearance.</li></ol><div class="example">Example: 3, 6, 12, 24, __. Each term is multiplied by 2, so the next term is 48.</div></div>`}
function quizMarkup(id){let qs=quizBank[id]||[];if(!qs.length)return `<div class="empty">The topic map is available. This subject’s full original question bank is not yet included in this website build.</div>`;return `<div class="quiz" data-quiz="${id}">${qs.map((q,i)=>`<div class="question" data-question="${i}"><div class="q-meta">Question ${i+1} · Practice</div><h3>${q[0]}</h3><div class="options">${q[1].map((o,j)=>`<label class="option"><input type="radio" name="${id}-${i}" value="${j}"><span><strong>${String.fromCharCode(65+j)}.</strong> ${o}</span></label>`).join('')}</div><div class="feedback hidden" id="feedback-${id}-${i}"></div></div>`).join('')}<button class="btn btn-primary" data-check-quiz="${id}">Check answers</button> <span class="small muted" id="quiz-result-${id}"></span></div>`}
function mocks(){return `<div class="eyebrow">ASSESSMENT</div><h1>Mock examinations</h1><p class="lead">Use these as suggested training sets. They are original practice resources, not official ACEE examinations.</p><div class="notice"><strong>Timing warning</strong>Official ACEE item counts, section timings, and scoring rules have not been independently confirmed here. The suggested timing below is for personal practice only.</div><div class="grid three">${[['Diagnostic','Foundational and moderate questions','Find initial strengths and gaps.'],['Intermediate','Mixed, multi-step questions','Build accuracy and pacing.'],['Advanced','More demanding applications and deductions','Practise handling unfamiliar questions.']].map((x,i)=>`<div class="card"><span class="tag">MOCK ${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p><p>${x[2]}</p><div class="card-bottom"><button class="btn" data-mock="${i}">Open practice set</button></div></div>`).join('')}</div><div id="mock-area"></div><div class="section-head"><div><h2>Record a mock result</h2><p>Save your score and identify what to revisit.</p></div></div><div class="panel"><div class="grid two"><div class="field"><label>Mock exam</label><select id="mock-name"><option>Diagnostic</option><option>Intermediate</option><option>Advanced</option></select></div><div class="field"><label>Correct answers</label><input type="number" id="mock-correct" min="0" value="0"></div><div class="field"><label>Total questions attempted</label><input type="number" id="mock-total" min="1" value="20"></div><div class="field"><label>Topics to revisit</label><input id="mock-topics" placeholder="e.g. algebra, inference, genetics"></div></div><button class="btn btn-primary" id="save-mock">Save mock result</button></div><div id="mock-history" class="section-head"><div><h2>Saved results</h2></div></div>${state.mockScores.length?state.mockScores.map(x=>`<div class="topic-row"><span><strong>${esc(x.name)} — ${x.correct}/${x.total} (${Math.round(x.correct/x.total*100)}%)</strong><small>${esc(x.date)} · Review: ${esc(x.topics||'Not specified')}</small></span></div>`).join(''):'<div class="empty">No mock results recorded yet.</div>'}`}
function videoPage(){return `<div class="eyebrow">LEARNING RESOURCES</div><h1>Video library</h1><p class="lead">Use videos to clarify concepts after reading the written lesson. Verify exact video titles and use channel search when a direct individual link is not available.</p><div class="notice blue"><strong>Verification standard</strong>Channel links below are provided as discovery starting points. They are not presented as a verified list of specific ACEE-preparation videos. A known topic-specific video should be checked before being labelled a direct recommendation.</div><input class="search" id="video-search" placeholder="Search channels or topics..."><div id="video-list">${videos.map(v=>`<div class="resource" data-search="${esc((v.ch+' '+v.topic+' '+v.desc).toLowerCase())}"><div class="play">▶</div><div><span class="tag">${v.level}</span><h3>${v.ch}</h3><p><strong>${v.topic}</strong> — ${v.desc}</p><a href="${v.url}" target="_blank" rel="noopener">Open resource ↗</a></div></div>`).join('')}</div><div class="section-head"><div><h2>Suggested viewing order</h2><p>Match the video to the topic currently being studied.</p></div></div><div class="grid two">${[['Mathematics','Fractions → percentages → ratios → algebra → equations → functions → geometry → probability'],['Science','Cells → genetics → matter and atoms → bonding → reactions → motion → forces → Earth systems'],['Practice method','Write 3–5 key points, pause before worked answers, then solve a similar problem independently.'],['Verification','If an exact video cannot be verified, use the channel’s search rather than an invented direct URL.']].map(x=>`<div class="card"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div>`}
function studyPlan(){const plans={30:{title:'30-day intensive',duration:'60–120 minutes/day',weeks:[['Days 1–3','Diagnostic, grammar foundations, arithmetic and percentages'],['Days 4–7','Reading skills, algebra, cells and atomic structure'],['Days 8–12','Sentence correction, inference, equations, bonding and motion'],['Days 13–17','Geometry, statistics, body systems, chemical reactions'],['Days 18–22','Logical reasoning, functions, physics and Earth science'],['Days 23–26','Mixed practice and error repair'],['Days 27–29','Diagnostic re-test and advanced mock'],['Day 30','Light review, formula sheet, rest and logistics']]},60:{title:'60-day balanced',duration:'45–90 minutes/day',weeks:[['Week 1','Diagnostic, grammar, number sense'],['Week 2','Vocabulary, sentence correction, fractions and algebra'],['Week 3','Reading comprehension, equations, cell biology'],['Week 4','Functions, geometry, atomic structure and bonding'],['Week 5','Statistics, probability, genetics and chemical reactions'],['Week 6','Kinematics, forces, energy, Earth science'],['Week 7','Abstract/logical reasoning and mixed practice'],['Week 8','Intermediate mock, repair weak topics, cumulative review'],['Days 57–60','Advanced mock, formula review, rest and logistics']]},90:{title:'90-day extended',duration:'30–75 minutes/day',weeks:[['Weeks 1–2','Diagnostic, grammar, arithmetic, study routine'],['Weeks 3–4','Vocabulary, sentence completion, algebra, cells'],['Weeks 5–6','Reading passages, functions, genetics, chemistry'],['Weeks 7–8','Geometry, probability, motion, forces, waves'],['Weeks 9–10','Earth science, astronomy, reasoning patterns, mixed quizzes'],['Weeks 11–12','Targeted remediation, spaced review, intermediate mock'],['Week 13','Advanced mock, final review, rest and test logistics']]}};let p=plans[state.plan]||plans[60];return `<div class="eyebrow">PREPARATION SYSTEM</div><h1>Study plans</h1><p class="lead">Choose a preparation window and adapt it to your baseline, school workload, and current admission schedule.</p><div class="tabs">${[['30','30 days'],['60','60 days'],['90','90 days']].map(x=>`<button class="tab ${state.plan===x[0]?'active':''}" data-plan="${x[0]}">${x[1]}</button>`).join('')}</div><div class="panel"><span class="tag">SELECTED PLAN</span><h2 style="margin-top:9px">${p.title}</h2><p class="muted">${p.duration}. Suggested workload, not a required minimum.</p><div class="field"><label>Plan start date</label><input type="date" id="plan-start" value="${esc(state.planStart)}"></div><div class="notice blue">Study cycle: learn the concept → work through an example → watch a relevant lesson → answer questions independently → analyse mistakes → review after a delay → test retention with mixed questions.</div></div><div class="section-head"><div><h2>Schedule</h2><p>Check off a period after completing its learning and review tasks.</p></div></div><div class="topic-list">${p.weeks.map((w,i)=>`<label class="topic-row"><input type="checkbox" class="check" data-done="plan-${state.plan}-${i}" ${state.done['plan-'+state.plan+'-'+i]?'checked':''}><span><strong>${w[0]}</strong><small>${w[1]}</small></span></label>`).join('')}</div><div class="section-head"><div><h2>Weekly routine</h2></div></div><div class="grid two">${[['Spaced repetition','Review new concepts after 1 day, 3 days, and 7 days; adjust when recall is weak.'],['Cumulative quiz','At the end of each week, answer mixed questions from old and new topics.'],['Rest and catch-up','Reserve at least one lighter day each week; move unfinished work instead of abandoning the plan.'],['Mock timing','Use consistent suggested timing for comparison, but do not mistake it for official ACEE timing.']].map(x=>`<div class="card"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div>`}
function tracker(){return `<div class="eyebrow">PERFORMANCE</div><h1>Progress tracker</h1><p class="lead">Record sessions, classify mistakes, and decide what to study next based on evidence.</p><div class="panel"><h2>Log a study session</h2><div class="grid two"><div class="field"><label>Date</label><input type="date" id="log-date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Component</label><select id="log-component">${modules.map(m=>`<option>${m.title}</option>`).join('')}</select></div><div class="field"><label>Topic</label><input id="log-topic" placeholder="e.g. subject–verb agreement"></div><div class="field"><label>Minutes studied</label><input type="number" id="log-minutes" min="1" value="30"></div><div class="field"><label>Questions attempted</label><input type="number" id="log-attempted" min="0" value="10"></div><div class="field"><label>Correct answers</label><input type="number" id="log-correct" min="0" value="7"></div><div class="field"><label>Main error type</label><select id="log-error"><option>Knowledge gap</option><option>Misunderstood question</option><option>Incorrect formula or procedure</option><option>Calculation error</option><option>Weak inference</option><option>Pattern misidentification</option><option>Careless mistake</option><option>Time-management issue</option><option>None identified</option></select></div><div class="field"><label>Next review date</label><input type="date" id="log-review"></div><div class="field" style="grid-column:1/-1"><label>Notes / concepts to revisit</label><textarea id="log-notes" placeholder="What caused the errors? What will you do differently?"></textarea></div></div><button class="btn btn-primary" id="save-log">Save study session</button></div><div class="section-head"><div><h2>Session history</h2><p>Accuracy = correct answers ÷ attempted × 100.</p></div><button class="btn" id="export-logs">Export CSV</button></div>${state.logs.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Component / topic</th><th>Time</th><th>Accuracy</th><th>Error type</th><th>Next review</th><th></th></tr></thead><tbody>${state.logs.map((l,i)=>`<tr><td>${esc(l.date)}</td><td><strong>${esc(l.component)}</strong><br>${esc(l.topic)}</td><td>${l.minutes} min</td><td>${l.attempted?Math.round(l.correct/l.attempted*100)+'%':'—'} (${l.correct}/${l.attempted})</td><td>${esc(l.error)}</td><td>${esc(l.review||'—')}</td><td><button class="small-btn" data-delete-log="${i}">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No study sessions logged yet.</div>'}<div class="section-head"><div><h2>How to interpret mistakes</h2></div></div><div class="grid two">${[['Knowledge gap','Relearn the concept, then solve 3–5 basic questions.'],['Misunderstood question','Underline command words, units, and constraints before solving.'],['Incorrect formula/procedure','Write the correct formula and practise selecting when to use it.'],['Calculation error','Show intermediate steps and check signs, units, and arithmetic.'],['Weak inference','Return to the passage and locate exact supporting evidence.'],['Pattern misidentification','Record each attribute separately: count, orientation, position, shading, size.'],['Careless mistake','Use a short final-check routine.'],['Time-management issue','Practise in short timed sets and track time per item.']].map(x=>`<div class="card"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div>`}
function formula(){return `<div class="eyebrow">QUICK REFERENCE</div><h1>Formula sheet</h1><p class="lead">Foundational formulas for general entrance-exam practice. Confirm the expected scope before prioritising advanced formulas.</p><div class="section-head"><div><h2>Mathematics</h2></div></div><div class="table-wrap"><table><tbody>${[['Percentage','(part ÷ whole) × 100%'],['Percent change','(new − original) ÷ original × 100%'],['Average speed','distance ÷ time'],['Distance','speed × time'],['Simple interest','I = Prt'],['Rectangle area','A = lw'],['Triangle area','A = ½bh'],['Circle area','A = πr²'],['Circumference','C = 2πr = πd'],['Pythagorean theorem','a² + b² = c²'],['Slope','m = (y₂ − y₁) ÷ (x₂ − x₁)'],['Distance between points','√[(x₂−x₁)² + (y₂−y₁)²]'],['Midpoint','((x₁+x₂)/2, (y₁+y₂)/2)'],['Mean','sum of values ÷ number of values'],['Probability','favourable outcomes ÷ total equally likely outcomes']].map(x=>`<tr><td><strong>${x[0]}</strong></td><td>${x[1]}</td></tr>`).join('')}</tbody></table></div><div class="section-head"><div><h2>Chemistry</h2></div></div><div class="table-wrap"><table><tbody>${[['Density','mass ÷ volume'],['Moles','mass ÷ molar mass'],['Particles','moles × Avogadro constant (6.022 × 10²³ mol⁻¹)'],['Molarity','moles of solute ÷ litres of solution'],['Kelvin conversion','K = °C + 273.15'],['Ideal gas law','PV = nRT'],['pH','−log₁₀[H⁺] for the usual introductory concentration definition'],['Conservation','Atoms of each element are balanced on both sides of a chemical equation']].map(x=>`<tr><td><strong>${x[0]}</strong></td><td>${x[1]}</td></tr>`).join('')}</tbody></table></div><div class="section-head"><div><h2>Physics</h2></div></div><div class="table-wrap"><table><tbody>${[['Velocity','displacement ÷ time'],['Acceleration','(final velocity − initial velocity) ÷ time'],['Uniform acceleration','v = u + at'],['Displacement under uniform acceleration','s = ut + ½at²'],['Newton’s second law','F = ma'],['Weight near Earth','W = mg'],['Work','W = Fd cos θ'],['Kinetic energy','KE = ½mv²'],['Gravitational potential energy near Earth','PE = mgh'],['Power','work ÷ time'],['Momentum','p = mv'],['Ohm’s law','V = IR'],['Electrical power','P = VI']].map(x=>`<tr><td><strong>${x[0]}</strong></td><td>${x[1]}</td></tr>`).join('')}</tbody></table></div><div class="notice">Use SI units unless the question specifies otherwise. Convert units before substituting values. Some equations assume particular conditions, such as constant acceleration or uniform gravitational field.</div>`}
function glossaryPage(){return `<div class="eyebrow">REFERENCE</div><h1>Glossary</h1><p class="lead">Key terms used throughout the reviewer.</p><input class="search" id="glossary-search" placeholder="Search terms..."><div id="glossary-list">${glossary.map(g=>`<div class="topic-row" data-term="${esc((g[0]+' '+g[1]).toLowerCase())}"><span><strong>${g[0]}</strong><small>${g[1]}</small></span></div>`).join('')}</div>`}
function bindPage(){
$$('[data-go]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.go)));
$$('[data-done]').forEach(c=>c.addEventListener('change',()=>{state.done[c.dataset.done]=c.checked;save();if(state.view==='dashboard')render()}));
$$('[data-save-note]').forEach(b=>b.addEventListener('click',()=>{state.notes[b.dataset.saveNote]=$('#notes-'+b.dataset.saveNote).value;save();b.textContent='Saved';setTimeout(()=>b.textContent='Save notes',900)}));
$$('[data-check-quiz]').forEach(b=>b.addEventListener('click',()=>checkQuiz(b.dataset.checkQuiz)));
$$('[data-plan]').forEach(b=>b.addEventListener('click',()=>{state.plan=b.dataset.plan;save();render()}));
const ps=$('#plan-start');if(ps)ps.addEventListener('change',()=>{state.planStart=ps.value;save()});
const vs=$('#video-search');if(vs)vs.addEventListener('input',()=>$$('[data-search]').forEach(el=>el.classList.toggle('hidden',!el.dataset.search.includes(vs.value.toLowerCase()))));
const gs=$('#glossary-search');if(gs)gs.addEventListener('input',()=>$$('[data-term]').forEach(el=>el.classList.toggle('hidden',!el.dataset.term.includes(gs.value.toLowerCase()))));
const sl=$('#save-log');if(sl)sl.addEventListener('click',saveLog);
const ex=$('#export-logs');if(ex)ex.addEventListener('click',exportLogs);
$$('[data-delete-log]').forEach(b=>b.addEventListener('click',()=>{state.logs.splice(Number(b.dataset.deleteLog),1);save();render()}));
$$('[data-mock]').forEach(b=>b.addEventListener('click',()=>openMock(Number(b.dataset.mock))));
const sm=$('#save-mock');if(sm)sm.addEventListener('click',saveMock);
}
function checkQuiz(id){const qs=quizBank[id]||[];let correct=0,answered=0;qs.forEach((q,i)=>{const picked=document.querySelector(`input[name="${id}-${i}"]:checked`);const fb=$(`#feedback-${id}-${i}`);fb.classList.remove('hidden','correct','incorrect');if(picked){answered++;if(Number(picked.value)===q[2]){correct++;fb.classList.add('correct');fb.innerHTML='<strong>Correct.</strong> '+esc(q[3])}else{fb.classList.add('incorrect');fb.innerHTML='<strong>Correct answer: '+String.fromCharCode(65+q[2])+'.</strong> '+esc(q[3])}}else{fb.classList.add('incorrect');fb.innerHTML='<strong>Unanswered.</strong> Correct answer: '+String.fromCharCode(65+q[2])+'. '+esc(q[3])}});const pct=Math.round(correct/qs.length*100);$('#quiz-result-'+id).textContent=`Score: ${correct}/${qs.length} (${pct}%)`;state.quizScores[id]=pct;save()}
function saveLog(){const attempted=Number($('#log-attempted').value),correct=Number($('#log-correct').value);if(correct>attempted||attempted<0){alert('Correct answers cannot exceed questions attempted.');return}state.logs.unshift({date:$('#log-date').value,component:$('#log-component').value,topic:$('#log-topic').value,minutes:Number($('#log-minutes').value),attempted,correct,error:$('#log-error').value,review:$('#log-review').value,notes:$('#log-notes').value});save();render()}
function exportLogs(){const rows=[['Date','Component','Topic','Minutes','Attempted','Correct','Accuracy','Error type','Next review','Notes'],...state.logs.map(l=>[l.date,l.component,l.topic,l.minutes,l.attempted,l.correct,l.attempted?Math.round(l.correct/l.attempted*100)+'%':'',l.error,l.review,l.notes])];const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='acee-study-log.csv';a.click();URL.revokeObjectURL(url)}
function openMock(n){const area=$('#mock-area');const keys=['english','reading','math','science','reasoning'];const chosen=[];keys.forEach(k=>(quizBank[k]||[]).slice(0,n===0?1:n===1?2:3).forEach(q=>chosen.push({key:k,q})));area.innerHTML=`<div class="panel" style="margin-top:16px"><div class="eyebrow">MOCK ${n+1} · SUGGESTED TRAINING SET</div><h2>${['Diagnostic','Intermediate','Advanced'][n]} practice set</h2><p class="muted small">${chosen.length} selected questions from the currently available sample bank. This is not yet a full-length mock exam.</p>${chosen.map((x,i)=>`<div class="question"><div class="q-meta">${x.key} · Question ${i+1}</div><h3>${x.q[0]}</h3><div class="options">${x.q[1].map((o,j)=>`<label class="option"><input type="radio" name="mock${n}-${i}" value="${j}"><span>${String.fromCharCode(65+j)}. ${o}</span></label>`).join('')}</div><div class="feedback hidden" id="mf-${n}-${i}"></div></div>`).join('')}<button class="btn btn-primary" id="grade-mock">Grade this set</button><span class="small muted" id="mock-set-score"></span></div>`;$('#grade-mock').addEventListener('click',()=>{let c=0;chosen.forEach((x,i)=>{const p=document.querySelector(`input[name="mock${n}-${i}"]:checked`),f=$(`#mf-${n}-${i}`);f.classList.remove('hidden','correct','incorrect');if(p&&Number(p.value)===x.q[2]){c++;f.classList.add('correct');f.textContent='Correct. '+x.q[3]}else{f.classList.add('incorrect');f.textContent='Answer: '+String.fromCharCode(65+x.q[2])+'. '+x.q[3]}});$('#mock-set-score').textContent=` Score: ${c}/${chosen.length} (${Math.round(c/chosen.length*100)}%)`;});area.scrollIntoView({behavior:'smooth',block:'start'})}
function saveMock(){const correct=Number($('#mock-correct').value),total=Number($('#mock-total').value);if(total<1||correct<0||correct>total){alert('Enter a valid score. Correct answers must not exceed total questions.');return}state.mockScores.unshift({name:$('#mock-name').value,correct,total,topics:$('#mock-topics').value,date:new Date().toISOString().slice(0,10)});save();render()}
$('#main-nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)setView(b.dataset.view)});
$('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#reset-progress').addEventListener('click',()=>{if(confirm('Clear all locally saved ACEE reviewer progress, notes, logs, and scores?')){localStorage.removeItem(STORE);state={...defaults};setView('dashboard')}});
render();
